} onChange={e=>access.update({pitch:Number(e.target.value)})} className=\"mt-2 min-h-11 w-full\"/></label>\n      <button type=\"button\" className=\"af-access-text-button\" onClick={()=>access.update({rate:DEFAULT_SETTINGS.rate,pitch:DEFAULT_SETTINGS.pitch,voiceURI:'',localVoicesOnly:true})}>Reset voice settings</button>\n     </section>\n     <section><h3 className=\"text-lg font-semibold\">Speak a question</h3><label className=\"mt-3 flex min-h-11 items-start gap-3 rounded-xl border border-gray-200 p-3\"><input type=\"checkbox\" checked={settings.voiceInput} onChange={e=>access.update({voiceInput:e.target.checked})} className=\"mt-1 h-5 w-5 shrink-0\"/><span className=\"text-sm font-medium\">Enable voice input</span></label><p className=\"mt-2 text-xs leading-6 text-gray-700\">Off by default. Your browser may send microphone audio to its speech provider and may need an internet connection. Recording starts only after you press Speak a question. Transcribed text is editable and is never submitted automatically. Browser and language support varies.</p></section>\n     <p className=\"rounded-xl bg-indigo-50 p-4 text-xs leading-6 text-indigo-950\">Keep using your normal screen reader, browser zoom and keyboard tools. These controls provide additional options; they do not establish full accessibility compliance. Voice support does not change the free tutor’s supported-question limits. Embedded tools may have their own settings.</p>\n    </div>\n    <div className=\"af-access-panel-footer\"><button type=\"button\" onClick={access.reset} className=\"min-h-11 rounded-xl border-2 border-red-700 bg-white px-4 py-2 text-sm font-semibold text-red-800\">Reset all accessibility settings</button><button type=\"button\" onClick={onClose} className=\"min-h-11 rounded-xl bg-indigo-700 px-5 py-2 text-sm font-semibold text-white\">Done</button><p className=\"w-full text-xs leading-5 text-gray-700\">Reset stops voice activity and restores defaults. Your lesson results and language choices are kept.</p></div>\n   </div>\n  </dialog>,document.body)}\n </>;\n}\n", "src/lib/accessibility/settings.ts": "export const ACCESSIBILITY_KEY='afactor-accessibility-v1';\nexport type AccessibilitySettings={textScale:number;readingSpace:boolean;strongFocus:boolean;underlineLinks:boolean;reduceMotion:boolean;rate:number;pitch:number;voiceURI:string;localVoicesOnly:boolean;voiceInput:boolean};\nexport const DEFAULT_SETTINGS:AccessibilitySettings={textScale:1,readingSpace:false,strongFocus:false,underlineLinks:false,reduceMotion:false,rate:1,pitch:1,voiceURI:'',localVoicesOnly:true,voiceInput:false};\nexport function sanitizeSettings(value:unknown):AccessibilitySettings {\n const v=value&&typeof value==='object'?value as Record<string,unknown>:{};\n const numeric=(key:keyof AccessibilitySettings,min:number,max:number)=>typeof v[key]==='number'&&Number.isFinite(v[key])?Math.min(max,Math.max(min,v[key] as number)):DEFAULT_SETTINGS[key] as number;\n const bool=(key:keyof AccessibilitySettings)=>typeof v[key]==='boolean'?v[key] as boolean:DEFAULT_SETTINGS[key] as boolean;\n return {textScale:numeric('textScale',1,1.5),readingSpace:bool('readingSpace'),strongFocus:bool('strongFocus'),underlineLinks:bool('underlineLinks'),reduceMotion:bool('reduceMotion'),rate:numeric('rate',.6,1.5),pitch:numeric('pitch',.8,1.2),voiceURI:typeof v.voiceURI==='string'?v.voiceURI.slice(0,500):'',localVoicesOnly:bool('localVoicesOnly'),voiceInput:bool('voiceInput')};\n}\nexport function speechLanguage(language:string){return ({en:'en-NG',yo:'yo-NG',ha:'ha-NG',ig:'ig-NG'} as Record<string,string>)[language]||language||'en-NG';}\nexport function speechText(text:string,language:string){\n if(!language.startsWith('en'))return text;\n return text.replace(/F\\s*=\\s*ma\\b/g,' force equals mass times acceleration ').replace(/V\\s*=\\s*IR\\b/g,' voltage equals current times resistance ').replace(/v\\s*=\\s*fλ/g,' wave speed equals frequency times wavelength ').replace(/m\\/s²/g,' metres per second squared ').replace(/m\\/s/g,' metres per second ').replace(/²/g,' squared ').replace(/³/g,' cubed ').replace(/₀/g,' zero ').replace(/₁/g,' one ').replace(/₂/g,' two ').replace(/λ/g,' wavelength ').replace(/θ/g,' theta ').replace(/π/g,' pi ').replace(/Ω/g,' ohms ').replace(/×/g,' times ').replace(/÷/g,' divided by ').replace(/=/g,' equals ').replace(/−/g,' minus ');\n}\nexport function speechChunks(text:string,max=300){const words=text.replace(/\\s+/g,' ').trim().split(' ');const chunks:string[]=[];let chunk='';for(const word of words){if(chunk&&chunk.length+word.length+1>max){chunks.push(chunk);chunk='';}chunk+=(chunk?' ':'')+word;}if(chunk)chunks.push(chunk);return chunks;}\nexport function normalizeDictation(text:string,language:string){if(!language.startsWith('en'))return text;return text.replace(/\\bvolts?\\b/gi,'V').replace(/\\bnewtons?\\b/gi,'N').replace(/\\bkilograms?\\b/gi,'kg').replace(/\\bhertz\\b/gi,'Hz').replace(/\\bmet(?:re|er)s? per second\\b/gi,'m/s').replace(/\\bequals?\\b/gi,'=');}\n", "capstone/ACCESSIBILITY_START_HERE.md": "# Accessibility and voice support\n\nRun `bash patch-accessibility-voice.sh` from the project root, then restart `npm run dev` and refresh. The Accessibility button is the round person icon at the bottom left. Your subject dropdown, Try now button and AI explainer remain as configured.\n\n## Adjustable and resettable controls\n\n- Text size: 100–150%, with a one-click text reset. Browser zoom still works independently.\n- More paragraph line and letter spacing.\n- Stronger keyboard focus indicators.\n- Underlined links.\n- Reduced CSS/interface motion. Simulation animations keep their own Run/Pause controls.\n- Read-aloud voice, rate, pitch and on-device-voice preference.\n- Voice input, disabled by default until enabled in settings.\n- Reset all accessibility settings: restores defaults, stops speech/microphone activity and removes the saved accessibility preference. It keeps quiz results, application language choices and other application data.\n\nSettings are saved only in this browser under afactor-accessibility-v1. No student profile or disability information is collected. If storage is unavailable, settings still work for the current session. Different devices and browsers have separate preferences.\n\n## Read aloud\n\nRead aloud buttons appear in the topic explainer, tutor lessons and prepared tutor replies. Pause, Resume and Stop are available while reading. Nothing reads automatically. A basic English spoken form is provided for a few common formulae and symbols; this is not a general mathematical screen reader.\n\nThe accessibility panel can also read up to the first 12,000 characters of the current page's main text. It does not automatically describe canvases, charts or iframe contents. Visible written text remains available for learners who do not use audio.\n\nBy default only browser voices marked as on-device are eligible. Automatic voice selection matches the text's language. English, Yoruba, Hausa and Igbo text can only be spoken when the device exposes a matching voice; the patch does not install or manufacture voices. If a matching voice is unavailable, the app shows a clear message. It does not silently read Yoruba with an English voice. Turning off on-device-only mode may allow provider-backed voices that send text to that provider.\n\nVoice availability and installation are controlled by the operating system/browser. Reference: https://developer.mozilla.org/en-US/docs/Web/API/SpeechSynthesis/getVoices\n\n## Speak a question\n\nEnable voice input in Accessibility settings, return to the tutor or simulation prompt box, and press Speak a question. The browser may request microphone permission. Press Stop microphone to finish, review/edit the transcription and then submit using the normal button. It never submits automatically. Speech input appends to the current field, respecting the existing length limit. Common English spoken units and “equals” are normalised for the existing parser.\n\nYour browser's recognition service may process audio online. Support varies by browser and language; typing remains available when recognition is absent or permission is denied. The app does not save microphone recordings. Recognition stops on route/language changes, disabling voice input, opening settings or resetting accessibility settings.\n\nReference: https://developer.mozilla.org/en-US/docs/Web/API/SpeechRecognition\n\nThese features require no new paid AI API. They do not change the free demo's prepared-response and supported-topic limits.\n\n## Scope and verification\n\nThis is an accessibility improvement, not a claim of full WCAG conformance or suitability for every learner. Standard screen readers, keyboard access and browser zoom remain important. Embedded tools and simulation-specific graphics may need their own adaptations. Reduced interface motion does not stop scientific animations implemented in JavaScript.\n\nTypeScript and production build checks were completed. Settings sanitisation/defaults, speech-text helpers and installer behaviour were checked. Actual audio playback, microphone permission flows, keyboard interaction and physical-device visual testing require testing in the target browser; these were not verified through the unavailable managed browser preview.\n\nSuggested checks:\n\n1. Adjust each setting and reload; check that it is retained.\n2. Reset all settings; check normal appearance, no active speech, voice input off, and quiz results unchanged.\n3. Try Read aloud, Pause, Resume and Stop with an installed English voice.\n4. Try a local-language lesson with and without a matching installed voice.\n5. Enable dictation, deny permission once, then allow it and verify editable text.\n6. Navigate with Tab and use Skip to main content, Escape and modal close buttons.\n7. Test enlarged text on a phone and verify that the two floating helpers do not overlap.\n"};
function stop(message){console.error('Patch stopped: '+message+' No application files changed.');process.exit(1);}
if(!fs.existsSync('package.json')||!fs.existsSync('src/components/explorer/ResultCard.tsx'))stop('Run from your project root with the all-topic explorer installed.');
let ts;try{ts=require(path.join(root,'node_modules/typescript'));}catch{stop('Run npm install for your existing dependencies first.');}
function safe(file){let current=root;for(const part of file.split('/')){current=path.join(current,part);try{if(fs.lstatSync(current).isSymbolicLink())stop('Symbolic link at '+file);}catch(e){if(e.code!=='ENOENT')throw e;}}}
function read(file){safe(file);if(!fs.existsSync(file))stop('Missing expected file: '+file);return fs.readFileSync(file,'utf8');}
function ast(file,source){return ts.createSourceFile(file,source,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX);}
function walk(n,fn){fn(n);ts.forEachChild(n,c=>walk(c,fn));}
function addImport(file,source,name,module){if(source.includes("from '"+module+"'"))return source;const first=ast(file,source).statements[0],at=first&&ts.isExpressionStatement(first)&&ts.isStringLiteral(first.expression)?first.end:0;return source.slice(0,at)+"\nimport { "+name+" } from '"+module+"';\n"+source.slice(at);}
function afterParagraph(file,source,expression,jsx){const found=[];walk(ast(file,source),n=>{if(ts.isJsxExpression(n)&&n.expression?.getText()===expression&&ts.isJsxElement(n.parent)&&n.parent.openingElement.tagName.getText()==='p')found.push(n.parent);});if(found.length!==1)stop('Cannot locate '+expression+' in '+file);const at=found[0].end;return source.slice(0,at)+jsx+source.slice(at);}
const layout='src/app/layout.tsx';let l=read(layout);
if(!l.includes('<AccessibilityProvider')){const found=[];walk(ast(layout,l),n=>{if(ts.isJsxElement(n)&&n.openingElement.tagName.getText()==='body')found.push(n);});if(found.length!==1)stop('Cannot locate the root body.');const body=found[0];l=l.slice(0,body.closingElement.getStart())+'</AccessibilityProvider>'+l.slice(body.closingElement.getStart());l=l.slice(0,body.openingElement.end)+'<AccessibilityProvider>'+l.slice(body.openingElement.end);}
l=addImport(layout,l,'AccessibilityProvider','@/components/accessibility/AccessibilityProvider');if(!l.includes('@/components/accessibility/accessibility.css'))l="import '@/components/accessibility/accessibility.css';\n"+l;files[layout]=l;
const card='src/components/explorer/ResultCard.tsx';let c=read(card);
if(!c.includes('<ReadAloud'))c=afterParagraph(card,c,'result.explanation',"<ReadAloud language={result.language} text={[topic.title,result.explanation,topic.principle,result.calculation||''].join('. ')}/>");c=addImport(card,c,'ReadAloud','@/components/accessibility/ReadAloud');files[card]=c;
const prompt='src/components/ai/PromptBar.tsx';let p=read(prompt);
if(!p.includes('<SpeechInput')){const forms=[];walk(ast(prompt,p),n=>{if(ts.isJsxElement(n)&&n.openingElement.tagName.getText()==='form')forms.push(n);});if(forms.length!==1||!p.includes('setPrompt'))stop('Cannot locate the simulation prompt form.');const at=forms[0].getStart();p=p.slice(0,at)+"<SpeechInput language={language} onTranscript={text=>setPrompt(current=>(current+' '+text).trim().slice(0,1200))}/>"+p.slice(at);}p=addImport(prompt,p,'SpeechInput','@/components/accessibility/SpeechInput');files[prompt]=p;
const tutor='src/app/tutor/page.tsx';let t=read(tutor);
if(!t.includes('<ReadAloud'))t=afterParagraph(tutor,t,'lesson.objective',"<ReadAloud language={language} text={stage==='learn'?[lesson.title,lesson.explanation,lesson.example].join('. '):stage==='explore'?lesson.investigation:[lesson.question,...lesson.options,result?lesson.solution:''].join('. ')}/>");
if(!t.includes('<SpeechInput')){const forms=[];walk(ast(tutor,t),n=>{if(ts.isJsxElement(n)&&n.openingElement.tagName.getText()==='form')forms.push(n);});if(forms.length!==1||!t.includes('setQuestion'))stop('Cannot locate the tutor question form.');const at=forms[0].getStart();t=t.slice(0,at)+"<SpeechInput language={language} onTranscript={text=>setQuestion(current=>(current+' '+text).trim().slice(0,1200))}/>"+t.slice(at);}
if(!t.includes('text={demoAnswer(')){const replies=[];walk(ast(tutor,t),n=>{if(ts.isJsxExpression(n)&&n.expression&&ts.isCallExpression(n.expression)&&n.expression.expression.getText()==='demoAnswer'&&ts.isJsxElement(n.parent))replies.push(n);});if(replies.length!==1)stop('Cannot locate the prepared tutor reply.');const at=replies[0].end;t=t.slice(0,at)+'<ReadAloud language={language} text={demoAnswer(lesson.id, language, m.intent)}/>'+t.slice(at);}
t=addImport(tutor,t,'ReadAloud','@/components/accessibility/ReadAloud');t=addImport(tutor,t,'SpeechInput','@/components/accessibility/SpeechInput');files[tutor]=t;
for(const file of [...Object.keys(files),'.stem-tutor-backups'])safe(file);
const changed=Object.keys(files).filter(file=>!fs.existsSync(file)||fs.readFileSync(file,'utf8')!==files[file]);if(!changed.length){console.log('Accessibility and voice features are already installed.');process.exit(0);}
fs.mkdirSync('.stem-tutor-backups',{recursive:true});const backup=fs.mkdtempSync('.stem-tutor-backups/accessibility-voice-'),originals=new Map();
for(const file of changed){const original=fs.existsSync(file)?fs.readFileSync(file):null;originals.set(file,original);if(original!==null){const copy=path.join(backup,file);fs.mkdirSync(path.dirname(copy),{recursive:true});fs.writeFileSync(copy,original);}}
fs.writeFileSync(path.join(backup,'manifest.json'),JSON.stringify(changed.map(file=>({file,existed:originals.get(file)!==null})),null,2));
try{for(const file of changed){fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,files[file],'utf8');}}catch(error){for(const [file,original] of originals){if(original===null){if(fs.existsSync(file))fs.unlinkSync(file);}else fs.writeFileSync(file,original);}stop('Write failed; originals restored: '+error.message);}
console.log('Installed adjustable accessibility settings, read aloud and optional voice input.');console.log('Open the round Accessibility button at the bottom left.');console.log('Reset all accessibility settings restores defaults without clearing lesson data.');console.log('Backup: '+backup);console.log('Restart npm run dev. Guide: capstone/ACCESSIBILITY_START_HERE.md');
